CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, issuer text NOT NULL, subject text NOT NULL, name text NOT NULL, UNIQUE(issuer,subject));
CREATE TABLE web_sessions(token_hash text PRIMARY KEY, user_id uuid REFERENCES users, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE login_states(state_hash text PRIMARY KEY, nonce text NOT NULL, verifier text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE projects(id uuid PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), revision bigint NOT NULL DEFAULT 1, concurrency integer NOT NULL DEFAULT 5 CHECK(concurrency BETWEEN 1 AND 20), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_members(project_id uuid REFERENCES projects, user_id uuid REFERENCES users, role text NOT NULL CHECK(role IN ('owner','editor','viewer')), PRIMARY KEY(project_id,user_id));
CREATE TABLE credentials(id uuid PRIMARY KEY, project_id uuid REFERENCES projects, label text NOT NULL, ciphertext bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, UNIQUE(project_id,id));
CREATE TABLE resources(id uuid PRIMARY KEY, project_id uuid REFERENCES projects, kind text NOT NULL CHECK(kind IN ('agent','scenario')), title text NOT NULL, dataset_item_id uuid, archived boolean NOT NULL DEFAULT false, revision bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,id));
CREATE TABLE versions(id uuid PRIMARY KEY, project_id uuid REFERENCES projects, parent_id uuid, kind text NOT NULL CHECK(kind IN ('agent','scenario','environment','evaluator','simulator')), version_number integer NOT NULL, status text NOT NULL CHECK(status IN ('draft','published')), revision bigint NOT NULL DEFAULT 1, definition jsonb NOT NULL, definition_sha256 text, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, FOREIGN KEY(project_id,parent_id) REFERENCES resources(project_id,id), UNIQUE(parent_id,version_number), UNIQUE(project_id,id));
CREATE TABLE runs(id uuid PRIMARY KEY, project_id uuid REFERENCES projects, status text NOT NULL, verdict text, request jsonb NOT NULL, revision bigint NOT NULL DEFAULT 1, event_cursor bigint NOT NULL DEFAULT 0, cancel_requested boolean NOT NULL DEFAULT false, concurrency integer NOT NULL, queue_timeout_ms bigint NOT NULL DEFAULT 86400000, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz, UNIQUE(project_id,id));
CREATE TABLE sessions(id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL, scenario_version_id uuid NOT NULL, dataset_item_id uuid NOT NULL, repetition_index integer NOT NULL, seed bigint NOT NULL, status text NOT NULL DEFAULT 'queued', verdict text, revision bigint NOT NULL DEFAULT 1, current_attempt_no integer NOT NULL DEFAULT 1, current_evaluation_id uuid, primary_evaluation_id uuid, error jsonb, completeness jsonb NOT NULL DEFAULT '{"status":"unknown"}', FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,id), UNIQUE(project_id,run_id,id));
CREATE TABLE execution_attempts(session_id uuid REFERENCES sessions, attempt_no integer NOT NULL, dispatch_id uuid NOT NULL UNIQUE, plan_ref uuid NOT NULL UNIQUE, plan jsonb NOT NULL, plan_sha256 text NOT NULL, status text NOT NULL DEFAULT 'queued', worker_id uuid, lease_id uuid, lease_expiry timestamptz, deadline timestamptz, manifest_ref jsonb, manifest jsonb, last_seq bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,attempt_no));
CREATE TABLE evaluation_jobs(id uuid PRIMARY KEY, session_id uuid NOT NULL, attempt_no integer NOT NULL, evaluation_group_id uuid NOT NULL, purpose text NOT NULL CHECK(purpose IN ('primary','manual')), retry_index integer NOT NULL DEFAULT 1, current boolean NOT NULL DEFAULT true, evaluator_version_id uuid NOT NULL, status text NOT NULL DEFAULT 'queued', cancel_requested boolean NOT NULL DEFAULT false, worker_id uuid, lease_id uuid, lease_expiry timestamptz, deadline timestamptz, assessment_ref jsonb, assessment jsonb, error jsonb, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(session_id,attempt_no) REFERENCES execution_attempts);
CREATE UNIQUE INDEX one_current_evaluation ON evaluation_jobs(evaluation_group_id) WHERE current;
CREATE UNIQUE INDEX one_active_manual ON evaluation_jobs(session_id) WHERE purpose='manual' AND current AND status IN ('queued','running');
CREATE TABLE artifact_uploads(id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL, session_id uuid NOT NULL, attempt_no integer NOT NULL, evaluation_id uuid REFERENCES evaluation_jobs, producer text NOT NULL, kind text NOT NULL, object_key text NOT NULL UNIQUE, size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 0 AND 536870912), sha256 text NOT NULL, mime text NOT NULL, artifact_id uuid UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,run_id,session_id) REFERENCES sessions(project_id,run_id,id), FOREIGN KEY(session_id,attempt_no) REFERENCES execution_attempts);
CREATE TABLE artifact_index(id uuid PRIMARY KEY, upload_id uuid NOT NULL UNIQUE REFERENCES artifact_uploads, project_id uuid NOT NULL, run_id uuid NOT NULL, session_id uuid NOT NULL, attempt_no integer NOT NULL, evaluation_id uuid, producer text NOT NULL, kind text NOT NULL, object_key text NOT NULL UNIQUE, size_bytes bigint NOT NULL, sha256 text NOT NULL, mime text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), retain_until timestamptz NOT NULL, delete_pending boolean NOT NULL DEFAULT false);
CREATE TABLE outbox(id uuid PRIMARY KEY, subject text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0);
CREATE TABLE inbox(message_id uuid PRIMARY KEY, producer text NOT NULL, producer_event_id uuid NOT NULL, payload_sha256 text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(producer,producer_event_id));
CREATE TABLE progress_events(project_id uuid NOT NULL, run_id uuid NOT NULL, session_id uuid NOT NULL, attempt_no integer NOT NULL, session_seq bigint NOT NULL, producer_event_id uuid NOT NULL UNIQUE, payload jsonb NOT NULL, PRIMARY KEY(session_id,attempt_no,session_seq));
CREATE TABLE run_events(run_id uuid REFERENCES runs, cursor bigint NOT NULL, type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(run_id,cursor));
CREATE TABLE audit_log(id uuid PRIMARY KEY, project_id uuid, actor text NOT NULL, action text NOT NULL, resource_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE http_idempotency(actor uuid NOT NULL, route text NOT NULL, key text NOT NULL, body_hash text NOT NULL, response jsonb NOT NULL, status integer NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(actor,route,key));
CREATE TABLE quarantine(id uuid PRIMARY KEY, subject text NOT NULL, reason text NOT NULL, payload_sha256 text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stale_results(message_id uuid PRIMARY KEY, context jsonb NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX runs_project_created ON runs(project_id,created_at,id);
CREATE INDEX resources_project_created ON resources(project_id,created_at,id);
CREATE INDEX versions_project_created ON versions(project_id,created_at,id);
CREATE INDEX sessions_run ON sessions(run_id,id);
CREATE INDEX attempts_status_lease ON execution_attempts(status,lease_expiry);
CREATE INDEX evaluations_status_lease ON evaluation_jobs(status,lease_expiry);
CREATE INDEX outbox_unpublished ON outbox(created_at) WHERE published_at IS NULL;
CREATE INDEX artifact_project_created ON artifact_index(project_id,created_at,id);
CREATE FUNCTION protect_published_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='published' THEN RAISE EXCEPTION 'published versions are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_version BEFORE UPDATE OR DELETE ON versions FOR EACH ROW EXECUTE FUNCTION protect_published_version();
CREATE FUNCTION protect_plan() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.plan IS DISTINCT FROM OLD.plan OR NEW.plan_sha256 IS DISTINCT FROM OLD.plan_sha256 OR NEW.plan_ref IS DISTINCT FROM OLD.plan_ref THEN RAISE EXCEPTION 'runtime plan is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_runtime_plan BEFORE UPDATE ON execution_attempts FOR EACH ROW EXECUTE FUNCTION protect_plan();
CREATE FUNCTION bump_session_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.revision=OLD.revision+1; RETURN NEW; END $$;
CREATE TRIGGER session_revision BEFORE UPDATE ON sessions FOR EACH ROW EXECUTE FUNCTION bump_session_revision();
INSERT INTO schema_migrations(version) VALUES(1);
